// Category A — behavior borrowed from react-aria-components (its ProgressBar is the progressbar
// role, with the clamped percentage and value text); the ring is owned here.
import { ProgressBar as AriaProgressBar } from "react-aria-components";
import type { ProgressBarProps as AriaProgressBarProps } from "react-aria-components";
import type { CSSProperties, Ref } from "react";
import "./ProgressCircle.css";

export type ProgressCircleSize = "small" | "medium" | "large";

/** The value/range axis React Aria owns, plus the ring's size. Indeterminate is left out on purpose: see below. */
export interface ProgressCircleBaseProps
  extends Omit<AriaProgressBarProps, "className" | "children" | "isIndeterminate"> {
  /**
   * Diameter and stroke of the ring.
   *
   * @default "medium"
   */
  size?: ProgressCircleSize;
}

/**
 * ProgressCircle props.
 *
 * `role="progressbar"` requires an accessible name (WCAG 4.1.2), and a ring has no room for a
 * visible label, so the name comes from `aria-label` or `aria-labelledby` and omitting both does
 * not compile (component-contract.md §2, the discriminated-union carve-out).
 */
export type ProgressCircleProps = ProgressCircleBaseProps &
  ({ "aria-label": string } | { "aria-labelledby": string }) & {
    /** Additional class. sd-progress-circle is always retained. */
    className?: string;
    /** Passed to the root progress DOM element. */
    ref?: Ref<HTMLDivElement>;
  };

/**
 * ProgressCircle — the ring form of `ProgressBar`: one operation or goal advancing toward
 * completion, where a bar would not fit (beside an avatar, in a compact status row, a daily goal).
 *
 * **Determinate only.** Work of unknown length is a `Spinner`, which already draws a turning ring;
 * a second indeterminate ring here would give the library two loading indicators to choose between.
 */
export function ProgressCircle({
  size = "medium",
  value,
  minValue = 0,
  maxValue = 100,
  className,
  ref,
  ...props
}: ProgressCircleProps) {
  return (
    <AriaProgressBar
      {...props}
      ref={ref}
      value={value}
      minValue={minValue}
      maxValue={maxValue}
      // The type omits it; this keeps an untyped caller from reaching an empty indeterminate ring.
      isIndeterminate={false}
      data-size={size}
      className={className ? `sd-progress-circle ${className}` : "sd-progress-circle"}
    >
      {/* Borrow React Aria's own clamped percentage rather than recomputing it. */}
      {({ percentage }) => (
        <svg className="sd-progress-circle__svg" aria-hidden="true">
          <circle className="sd-progress-circle__track" />
          {/* `pathLength` makes the stroke's length 100, so the dash IS the percentage. */}
          <circle
            className="sd-progress-circle__fill"
            pathLength={100}
            data-empty={(percentage ?? 0) <= 0 || undefined}
            style={{ "--sd-progress-circle-fill-dash": `${percentage ?? 0} 100` } as CSSProperties}
          />
        </svg>
      )}
    </AriaProgressBar>
  );
}

/* ProgressCircle.css — .sd-progress-circle__* (a determinate progress ring)
   The ring is two circles in an SVG with no viewBox, so user units are CSS pixels and the stroke
   keeps its token width at every size; the radius is computed so the stroke sits inside the box. */
.sd-progress-circle {
  --sd-progress-circle-size-current: var(--sd-progress-circle-size-medium);
  --sd-progress-circle-stroke-width-current: var(--sd-progress-circle-stroke-width-medium);
  display: inline-flex;
  inline-size: var(--sd-progress-circle-size-current);
  block-size: var(--sd-progress-circle-size-current);
}
.sd-progress-circle[data-size="small"] {
  --sd-progress-circle-size-current: var(--sd-progress-circle-size-small);
  --sd-progress-circle-stroke-width-current: var(--sd-progress-circle-stroke-width-small);
}
.sd-progress-circle[data-size="large"] {
  --sd-progress-circle-size-current: var(--sd-progress-circle-size-large);
  --sd-progress-circle-stroke-width-current: var(--sd-progress-circle-stroke-width-large);
}

/* Start at twelve o'clock and run clockwise. `rotate`, not `transform`, so nothing that sets a
   transform on the ring can replace it (component-contract.md §6 rule 6). */
.sd-progress-circle__svg {
  inline-size: 100%;
  block-size: 100%;
  rotate: -90deg;
  overflow: visible;
}

.sd-progress-circle__track {
  cx: 50%;
  cy: 50%;
  r: calc(50% - var(--sd-progress-circle-stroke-width-current) / 2);
  fill: none;
  stroke: var(--sd-progress-circle-track);
  stroke-width: var(--sd-progress-circle-stroke-width-current);
}

.sd-progress-circle__fill {
  /* Set inline from React Aria's clamped percentage; this is the empty ring before it arrives. */
  --sd-progress-circle-fill-dash: 0 100;
  cx: 50%;
  cy: 50%;
  r: calc(50% - var(--sd-progress-circle-stroke-width-current) / 2);
  fill: none;
  stroke: var(--sd-progress-circle-fill);
  stroke-width: var(--sd-progress-circle-stroke-width-current);
  stroke-linecap: round;
  stroke-dasharray: var(--sd-progress-circle-fill-dash);
  transition: stroke-dasharray var(--sd-duration-slow) var(--sd-easing-standard);
}
/* A round cap draws a dot even at zero length, so an empty ring hides its fill. */
.sd-progress-circle__fill[data-empty] {
  visibility: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .sd-progress-circle__fill {
    transition: none;
  }
}
